-- Default content for the identity drift notification, at platform level (organizationId NULL).
--
-- A separate migration rather than an edit to 1794326104, because that one is already applied: editing an
-- applied migration leaves databases that ran the old version behind with no way to notice.
--
-- The wording states a fact about the record and never tells the member they did something wrong. The usual
-- trigger is an administrator correcting a name, so a text that reads as an accusation would be aimed at the
-- wrong person entirely.
INSERT INTO `email_templates` (`id`, `subject`, `groupId`, `webshopId`, `organizationId`, `type`, `text`, `html`, `json`, `updatedAt`, `createdAt`) VALUES
('4e8d1a69-2b73-4f05-9c84-7d1e6b3a2f57', 'Je goedkeuring voor het uittreksel uit het strafregister geldt niet meer', NULL, NULL, NULL, 'JudicialRecordIdentityChanged', '{{greeting}}\n\nDe naam of geboortedatum van {{firstNameMember}} {{lastNameMember}} is gewijzigd na de goedkeuring van het uittreksel uit het strafregister. De goedkeuring hoorde bij de vorige gegevens en geldt daardoor niet meer.\n\nEr is een nieuw uittreksel uit het strafregister (model 596.2) nodig. Vraag het aan bij je gemeente en lever het daarna hier af.\n\nUittreksel afleveren:\n{{judicialRecordUrl}}\n\nMet vriendelijke groeten,\n{{platformOrOrganizationName}}', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8" />\n<meta http-equiv="X-UA-Compatible" content="IE=edge" />\n<meta name="viewport" content="width=device-width,initial-scale=1.0" />\n<title>Je goedkeuring voor het uittreksel uit het strafregister geldt niet meer</title>\n</head>\n<body>\n<p>{{greeting}}</p><p><br></p><p>De naam of geboortedatum van {{firstNameMember}} {{lastNameMember}} is gewijzigd na de goedkeuring van het uittreksel uit het strafregister. De goedkeuring hoorde bij de vorige gegevens en geldt daardoor niet meer.</p><p><br></p><p>Er is een nieuw uittreksel uit het strafregister (model 596.2) nodig. Vraag het aan bij je gemeente en lever het daarna hier af.</p><p><br></p><div data-type="smartButton" data-id="judicialRecordUrl"><a href="{{judicialRecordUrl}}">Uittreksel afleveren</a></div><p><br></p><p>Met vriendelijke groeten,</p><p>{{platformOrOrganizationName}}</p>\n</body>\n</html>', '{"value":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"greeting"}}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"De naam of geboortedatum van ","type":"text"},{"type":"smartVariable","attrs":{"id":"firstNameMember"}},{"text":" ","type":"text"},{"type":"smartVariable","attrs":{"id":"lastNameMember"}},{"text":" is gewijzigd na de goedkeuring van het uittreksel uit het strafregister. De goedkeuring hoorde bij de vorige gegevens en geldt daardoor niet meer.","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Er is een nieuw uittreksel uit het strafregister (model 596.2) nodig. Vraag het aan bij je gemeente en lever het daarna hier af.","type":"text"}]},{"type":"paragraph"},{"type":"smartButton","attrs":{"id":"judicialRecordUrl"},"content":[{"text":"Uittreksel afleveren","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"Met vriendelijke groeten,","type":"text"}]},{"type":"paragraph","content":[{"type":"smartVariable","attrs":{"id":"platformOrOrganizationName"}}]}]},"version":426}', NOW(), NOW())
ON DUPLICATE KEY UPDATE id=id;
